const resp = $input.first().json;
if (!resp || resp.error || !Array.isArray(resp.items)) {
  return [{ json: { systems: [], systems_error: true } }];
}
const systems = resp.items.map(function (s) {
  const info = s.info || {};
  const uptimeHours = Math.round(((info.u || 0) / 3600) * 10) / 10;
  return {
    name: s.name || 'unknown',
    status: s.status || 'unknown',
    uptime_hours: uptimeHours,
    recent_reboot: uptimeHours < 24 && s.status === 'up'
  };
});
return [{ json: { systems: systems, systems_error: false } }];

const cfg = $('Get Uptime Kuma Monitors').first().json;
const hb = $input.first().json;
if (!cfg || cfg.error || !cfg.publicGroupList || !hb || hb.error || !hb.heartbeatList) {
  return [{ json: { error: true, up: 0, total: 0, problems: [] } }];
}
const names = {};
cfg.publicGroupList.forEach(function (g) {
  (g.monitorList || []).forEach(function (m) { names[m.id] = m.name; });
});
const labels = { 0: 'DOWN', 1: 'up', 2: 'PENDING', 3: 'MAINTENANCE' };
const ids = Object.keys(names);
const problems = [];
let up = 0;
ids.forEach(function (id) {
  const list = hb.heartbeatList[id] || [];
  const last = list[list.length - 1];
  if (!last) { problems.push(names[id] + ' - no heartbeat data'); return; }
  if (last.status === 1) { up += 1; } else { problems.push(names[id] + ' - ' + (labels[last.status] || 'unknown')); }
  const u24 = hb.uptimeList ? hb.uptimeList[id + '_24'] : undefined;
  if (last.status === 1 && typeof u24 === 'number' && u24 < 0.99) {
    problems.push(names[id] + ' - 24h uptime ' + (Math.round(u24 * 1000) / 10) + '%');
  }
});
return [{ json: { error: false, up: up, total: ids.length, problems: problems } }];

const raw = $('Set Configuration').first().json.backup_tasks || '';
const tasks = raw.split(',').map(function (part) {
  const bits = part.split('=');
  return { task_id: (bits[0] || '').trim(), task_name: (bits[1] || bits[0] || '').trim() };
}).filter(function (t) { return t.task_id && t.task_id !== 'TASK_ID'; });
if (!tasks.length) { return [{ json: { task_id: '', task_name: 'No backup tasks configured' } }]; }
return tasks.map(function (t) { return { json: t }; });

const statusMap = { 3: 'Successful', 4: 'Failed', 5: 'Partial', 6: 'Running' };
const tz = $('Set Configuration').first().json.timezone;
const tasks = $('Split Backup Task IDs').all();
const responses = $input.all();
function fmtDuration(sec) {
  const minutes = Math.floor(sec / 60);
  if (minutes < 60) { return minutes + 'm'; }
  return Math.floor(minutes / 60) + 'h ' + (minutes % 60) + 'm';
}
const backups = responses.map(function (item, i) {
  const resp = item.json;
  const name = tasks[i] ? tasks[i].json.task_name : 'Task ' + (i + 1);
  if (!resp || resp.error || resp.success === false) {
    const code = resp && resp.error && resp.error.code !== undefined ? ' (error ' + resp.error.code + ')' : '';
    return { name: name, status: 'Synology API unavailable' + code, time: '', duration: '' };
  }
  const versions = (resp.data && resp.data.versions) || [];
  if (!versions.length) { return { name: name, status: 'No data', time: '', duration: '' }; }
  const v = versions.slice().sort(function (a, b) { return b.time_end - a.time_end; })[0];
  const time = new Date(v.time_end * 1000).toLocaleTimeString('en-US', { timeZone: tz, hour: '2-digit', minute: '2-digit' });
  return { name: name, status: statusMap[v.status] || ('Unknown (' + v.status + ')'), time: time, duration: fmtDuration(v.time_end - v.time_start) };
});
return [{ json: { backups: backups } }];

const cfg = $('Set Configuration').first().json;
const beszel = $('Summarize Beszel Systems').first().json;
const kuma = $('Summarize Uptime Kuma Status').first().json;
const backups = $input.first().json.backups || [];
const today = new Date().toLocaleDateString('en-US', { timeZone: cfg.timezone, weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
const lines = ['**Homelab Brief** - ' + today, '', '**Systems (Beszel):**'];
if (!beszel.systems_error && beszel.systems.length) {
  beszel.systems.forEach(function (s) {
    lines.push('- ' + s.name + ' - ' + s.status + ' - ' + s.uptime_hours + 'h' + (s.recent_reboot ? ' (rebooted)' : ''));
  });
} else {
  lines.push('- Beszel data unavailable');
}
lines.push('', '**Services (Uptime Kuma):**');
if (kuma.error) {
  lines.push('- Uptime Kuma unavailable');
} else {
  lines.push('- ' + kuma.up + '/' + kuma.total + ' monitors up');
  kuma.problems.forEach(function (p) { lines.push('- ' + p); });
}
lines.push('', '**Backups (Synology Active Backup):**');
backups.forEach(function (b) {
  lines.push('- ' + b.name + ' - ' + b.status + (b.time ? ' - ' + b.time + ' (' + b.duration + ')' : ''));
});
return [{ json: { message: lines.join('\n').slice(0, 1900) } }];
